import logging
import re
import time

from taf.hw.rf_attenuator.devices.radiorack.radiorack import RadioRack
from taf.hw.rf_attenuator.exceptions import AttenuationReadError


class RadioRack8220(RadioRack):
    _READ_ATTENUATION_CMD = r'ATT'
    _PORT_VALUE_PATTERN = r"ATT\s+(\d+)\s+(\d+)"

    MAX_SUPPORTED_ATTENUATION = 127
    MIN_SUPPORTED_ATTENUATION = 0

    def _set_multiple_ports_decibel_attenuation(self, ports, attenuation_values):
        attenuation_values = [int(x) for x in attenuation_values]
        cmd = "ATT " + ";".join([str(port) + " " + str(value) for port, value in zip(ports, attenuation_values)])
        self._write_and_read(cmd)
        logging.info('Channels {} attenuation value is set to {}.'.format(ports, attenuation_values))

    def _verify_read_multiple_ports_attenuation_command_response(self, ports, output):
        port_value_dict = {}
        for port, value in re.findall(self._PORT_VALUE_PATTERN, output):
            port_value_dict[port] = value
        logging.info('Current attention value of all channels is: {}.'.format(port_value_dict))

        ports_not_exist = [str(x) for x in ports if str(x) not in port_value_dict.keys()]
        if ports_not_exist:
            raise AttenuationReadError(
                "Failed to read attenuation channels: {}. Ensure that these "
                "channels exist. If they do, connections limit might be exceeded. "
                "Try to stop the sessions that are currently running on the "
                "attenuator".format(ports_not_exist)
            )

        attenuation_values = [int(port_value_dict[str(x)]) for x in ports]
        logging.info('Channels {} attenuation is {}.'.format(ports, attenuation_values))
        return attenuation_values

    def _read_multiple_ports_decibel_attenuation(self, ports):
        time.sleep(0.5)
        output = self._write_and_read(self._READ_ATTENUATION_CMD)
        return self._verify_read_multiple_ports_attenuation_command_response(ports, output)

    def read_ports_attenuation(self, ports):
        return self._read_multiple_ports_decibel_attenuation(ports)
